     1	/* Nav: hamburger morph, overlay menu, hide-on-scroll-down (IntersectionObserver based, no scroll listener), current page marking. */
     2	(function () {
     3	  const burger = document.querySelector('.burger');
     4	  const menu = document.getElementById('menu');
     5	  const nav = document.querySelector('.nav');
     6	
     7	  function setMenu(open) {
     8	    if (!burger || !menu) return;
     9	    burger.setAttribute('aria-expanded', open ? 'true' : 'false');
    10	    menu.classList.toggle('is-open', open);
    11	    menu.setAttribute('aria-hidden', open ? 'false' : 'true');
    12	    document.body.classList.toggle('menu-open', open);
    13	    if (open) { const first = menu.querySelector('a'); first && first.focus({ preventScroll: true }); }
    14	  }
    15	  if (burger && menu) {
    16	    burger.addEventListener('click', () => setMenu(burger.getAttribute('aria-expanded') !== 'true'));
    17	    menu.addEventListener('click', (e) => { if (e.target.closest('a')) setMenu(false); });
    18	    document.addEventListener('keydown', (e) => { if (e.key === 'Escape') setMenu(false); });
    19	  }
    20	
    21	  // Mark the current page in the nav.
    22	  const here = location.pathname.replace(/index\.html$/, '');
    23	  document.querySelectorAll('.nav-links a, .menu a').forEach((a) => {
    24	    const p = a.getAttribute('href') || '';
    25	    if (p.startsWith('/#') || p === '/') return;
    26	    if (here.startsWith(p.replace(/#.*$/, ''))) a.setAttribute('aria-current', 'page');
    27	  });
    28	
    29	  // Compact nav after the hero: a sentinel at the top of the page is observed instead of listening to scroll.
    30	  if (nav) {
    31	    const sentinel = document.createElement('div');
    32	    sentinel.style.cssText = 'position:absolute;top:0;left:0;width:1px;height:140px;pointer-events:none;';
    33	    document.body.prepend(sentinel);
    34	    const io = new IntersectionObserver((entries) => {
    35	      nav.classList.toggle('is-scrolled', !entries[0].isIntersecting);
    36	    }, { threshold: 0 });
    37	    io.observe(sentinel);
    38	  }
    39	})();
=== motion.js ===
     1	/* Motion choreography (GSAP + ScrollTrigger). Every animation has a job:
     2	   hero entry = hierarchy (word, then cutouts, then the search); cutout parallax = depth; reveals = sequence; sticky stack = the four in order; blur-on-focus = attention. */
     3	(function () {
     4	  const reduced = document.documentElement.classList.contains('reduced') || window.matchMedia('(prefers-reduced-motion: reduce)').matches;
     5	  const hasGsap = typeof window.gsap !== 'undefined';
     6	
     7	  if (reduced || !hasGsap) {
     8	    document.querySelectorAll('.reveal').forEach((el) => el.classList.add('is-in'));
     9	    return;
    10	  }
    11	  gsap.registerPlugin(ScrollTrigger);
    12	
    13	  // ----- Hero entry: the word rises inside the sky, then the copy settles -----
    14	  const word = document.querySelector('[data-hero-word]');
    15	  if (word) {
    16	    const tl = gsap.timeline({ defaults: { ease: 'expo.out' } });
    17	    tl.from(word, { yPercent: 14, opacity: 0, duration: 1.1 }, 0)
    18	      .from('[data-hero-in]', { y: 22, opacity: 0, duration: 0.8, stagger: 0.07 }, 0.35);
    19	    // Scroll depth: the sky and the word recede slower than the foreground (real parallax between the two photo layers).
    20	    gsap.to('[data-hero-bg]', { yPercent: 12, ease: 'none', scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: true } });
    21	    gsap.to(word, { yPercent: 40, ease: 'none', scrollTrigger: { trigger: '.hero', start: 'top top', end: 'bottom top', scrub: true } });
    22	  }
    23	
    24	  // ----- Reveals: enter once with a short fade-up -----
    25	  document.querySelectorAll('.reveal').forEach((el) => {
    26	    gsap.to(el, {
    27	      opacity: 1, y: 0, duration: 0.7, ease: 'expo.out',
    28	      scrollTrigger: { trigger: el, start: 'top 90%', once: true },
    29	      onComplete: () => { el.classList.add('is-in'); el.style.willChange = 'auto'; },
    30	    });
    31	  });
    32	
    33	  // ----- The Four: sticky stack (canonical: pin every card but the last, next card shrinks the previous) -----
    34	  const stack = document.querySelector('[data-stack]');
    35	  const mq = window.matchMedia('(min-width: 900px)');
    36	  if (stack && mq.matches) {
    37	    const cards = gsap.utils.toArray('[data-rcard]');
    38	    cards.forEach((card, i) => {
    39	      if (i === cards.length - 1) return;
    40	      ScrollTrigger.create({ trigger: card, start: 'top top', endTrigger: cards[cards.length - 1], end: 'top top', pin: true, pinSpacing: false });
    41	      // The card underneath settles back a notch as the next one slides over it. No opacity change, so nothing ghosts through.
    42	      gsap.to(card.querySelector('.rcard-inner'), {
    43	        scale: 0.94, y: -24, ease: 'none',
    44	        scrollTrigger: { trigger: cards[i + 1], start: 'top bottom', end: 'top top', scrub: true },
    45	      });
    46	    });
    47	  }
    48	
    49	  // ----- Map pins drop in when the map section enters (handled by map.js via eat:map-ready) -----
    50	  window.addEventListener('eat:map-ready', () => {
    51	    const pins = document.querySelectorAll('.eat-pin');
    52	    if (!pins.length) return;
    53	    gsap.from(pins, { y: -18, opacity: 0, scale: 0.6, duration: 0.7, ease: 'back.out(2)', stagger: 0.07 });
    54	  });
    55	
    56	  // ----- Planner result swaps with a soft crossfade -----
    57	  window.addEventListener('eat:plan', () => {
    58	    const el = document.getElementById('planner-result'); if (!el) return;
    59	    gsap.fromTo(el.querySelectorAll('.stop, .walk'), { y: 14, opacity: 0 }, { y: 0, opacity: 1, duration: 0.6, ease: 'expo.out', stagger: 0.06 });
    60	  });
    61	
    62	  ScrollTrigger.refresh();
    63	})();

  1	/* App glue: live status lines, tonight board, category drawer, forms, tabs, toasts, click tracking for the on-device model. */
  2	(function () {
  3	  const D = window.EAT_DATA || { restaurants: [], categories: [], site: {} };
  4	  const H = window.EatHours;
  5	  const bySlug = Object.fromEntries(D.restaurants.map((r) => [r.slug, r]));
  6	  const $ = (s, c) => (c || document).querySelector(s);
  7	  const $$ = (s, c) => Array.from((c || document).querySelectorAll(s));
  8	  const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (m) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]));
  9	
 10	  // ---------- Toast ----------
 11	  let toastTimer;
 12	  function toast(msg) {
 13	    const t = $('#toast'); if (!t) return;
 14	    t.textContent = msg; t.classList.add('is-on');
 15	    clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove('is-on'), 2800);
 16	  }
 17	  window.EatToast = toast;
 18	
 19	  // ---------- Live status lines ----------
 20	  function paintStatus() {
 21	    if (!H) return;
 22	    const at = H.now();
 23	    $$('[data-status]').forEach((el) => {
 24	      const r = bySlug[el.dataset.status]; if (!r) return;
 25	      const line = H.statusLine(r, at);
 26	      const k = H.status(r.hours, at);
 27	      const b = r.bar_hours ? H.status(r.bar_hours, at) : null;
 28	      el.textContent = line;
 29	      el.classList.toggle('is-open', !!(k.open || (b && b.open)));
 30	      el.classList.toggle('is-soon', !!(k.open && k.closingSoon && !(b && b.open && b.closes > k.closes)));
 31	    });
 32	    $$('[data-status-short]').forEach((el) => {
 33	      const r = bySlug[el.dataset.statusShort]; if (!r) return;
 34	      const c = H.closesTonight(r);
 35	      el.textContent = c === null ? 'Closed today' : `Until ${H.fmt(c)}`;
 36	    });
 37	    paintTonight(at);
 38	  }
 39	
 40	  // ---------- Tonight board ----------
 41	  function paintTonight(at) {
 42	    const boards = $$('[data-tonight]'); if (!boards.length || !H) return;
 43	    at = at || H.now();
 44	    const rows = H.tonight(D.restaurants, at.day);
 45	    const label = at.date.toLocaleDateString(undefined, { weekday: 'long' });
 46	    boards.forEach((board) => {
 47	      const d = $('[data-tonight-date]', board); if (d) d.textContent = label;
 48	      rows.forEach((row) => {
 49	        const el = $(`[data-tonight-row="${row.slug}"]`, board); if (!el) return;
 50	        const r = bySlug[row.slug];
 51	        const time = $('[data-tonight-time]', el); const det = $('[data-tonight-detail]', el);
 52	        const stillOpen = row.closes !== null && row.closes > at.minutes;
 53	        el.classList.toggle('is-closed', !stillOpen);
 54	        if (time) time.textContent = row.closes === null ? 'Closed' : (stillOpen ? H.fmt(row.closes) : `Closed at ${H.fmt(row.closes)}`);
 55	        if (det) {
 56	          if (row.closes === null) det.textContent = r.hours_note && /closed/i.test(r.hours_note) ? r.hours_note : 'Closed tonight';
 57	          else if (row.barCloses && row.kitchenCloses && row.barCloses > row.kitchenCloses) det.textContent = `Kitchen ${H.fmt(row.kitchenCloses)}, bar ${H.fmt(row.barCloses)}`;
 58	          else det.textContent = row.past10 ? 'Kitchen and bar past 10' : row.past9 ? 'Open past 9' : row.past8 ? 'Open past 8' : 'Early night';
 59	        }
 60	      });
 61	    });
 62	  }
 63	
 64	  paintStatus();
 65	  setInterval(paintStatus, 60 * 1000);
 66	
 67	  // ---------- Directory drawer (category results) ----------
 68	  const drawer = $('#drawer');
 69	  function openDrawer(title, intro, itemsHtml) {
 70	    if (!drawer) return;
 71	    $('#drawer-title').textContent = title;
 72	    $('#drawer-body').innerHTML = `<p class="drawer-intro">${intro}</p>${itemsHtml}`;
 73	    drawer.classList.add('is-open'); drawer.setAttribute('aria-hidden', 'false');
 74	    document.body.classList.add('menu-open');
 75	    const first = $('#drawer-body a, #drawer-body button'); first && first.focus({ preventScroll: true });
 76	  }
 77	  function closeDrawer() {
 78	    if (!drawer) return;
 79	    drawer.classList.remove('is-open'); drawer.setAttribute('aria-hidden', 'true');
 80	    document.body.classList.remove('menu-open');
 81	    if (location.hash.startsWith('#c=')) history.replaceState(null, '', location.pathname + location.search);
 82	  }
 83	  document.addEventListener('click', (e) => {
 84	    if (e.target.closest('[data-drawer-close]')) closeDrawer();
 85	    const cat = e.target.closest('[data-drawer-category]');
 86	    if (cat) { e.preventDefault(); showCategory(cat.dataset.drawerCategory); }
 87	  });
 88	  document.addEventListener('keydown', (e) => { if (e.key === 'Escape') closeDrawer(); });
 89	
 90	  function resultCard(r, why, extraChips) {
 91	    const status = H ? H.statusLine(r) : '';
 92	    return `<a class="result" href="/r/${r.slug}/" data-track="result" data-slug="${r.slug}">
 93	      <span class="thumb"><img src="/${r.images.card || r.images.hero}" alt="" loading="lazy"></span>
 94	      <span><h4>${esc(r.name)}</h4><p class="why">${esc(why)}</p><span class="meta"><span class="chip chip-live">${esc(status)}</span>${(extraChips || []).map((c) => `<span class="chip">${esc(c)}</span>`).join('')}</span></span>
 95	    </a>`;
 96	  }
 97	
 98	  function showCategory(slug) {
 99	    const c = D.categories.find((x) => x.slug === slug); if (!c) return;
100	    const hits = D.restaurants.filter((r) => r.services && r.services[c.service]);
101	    // Rank with the on-device model if present.
102	    const ranked = window.EatSearch && window.EatSearch.rank ? window.EatSearch.rank(hits, { category: c.service }) : hits;
103	    let html = ranked.map((r) => resultCard(r, r.service_notes && r.service_notes[c.service] ? r.service_notes[c.service] : r.cuisine, [])).join('');
104	    if (!hits.length) {
105	      html = `<div class="card" style="padding:1.25rem"><h4>Not posted yet</h4><p class="small muted" style="margin-top:.4rem">None of the four lists ${esc(c.name.toLowerCase())} right now. ${c.slug === 'industry-specials' ? 'The partners are building it. <a href="/industry/" style="color:var(--accent);font-weight:600">Join the industry list</a> to hear first.' : c.slug === 'secret-menu' ? 'Follow the restaurants on Instagram, where off-menu items get announced.' : 'Check back, the directory updates as the restaurants post it.'}</p></div>`;
106	    }
107	    openDrawer(c.name, `${esc(c.blurb)} ${hits.length ? `${hits.length} of 4 on the corner.` : ''}`, html);
108	    if (window.EatSearch && window.EatSearch.learn) window.EatSearch.learn({ type: 'category', category: c.service });
109	    history.replaceState(null, '', `#c=${slug}`);
110	  }
111	  if (location.hash.startsWith('#c=')) showCategory(location.hash.slice(3));
112	  window.addEventListener('hashchange', () => { if (location.hash.startsWith('#c=')) showCategory(location.hash.slice(3)); });
113	  window.EatDrawer = { open: openDrawer, close: closeDrawer, resultCard, showCategory };
114	
115	  // ---------- Click learning ----------
116	  document.addEventListener('click', (e) => {
117	    const t = e.target.closest('[data-track]');
118	    if (t && window.EatSearch && window.EatSearch.learn) window.EatSearch.learn({ type: t.dataset.track, restaurant: t.dataset.slug });
119	  });
120	
121	  // ---------- Tabs ----------
122	  $$('[data-tabs]').forEach((wrap) => {
123	    wrap.addEventListener('click', (e) => {
124	      const tab = e.target.closest('[data-tab]'); if (!tab) return;
125	      $$('[data-tab]', wrap).forEach((t) => t.setAttribute('aria-selected', t === tab ? 'true' : 'false'));
126	      $$('[data-panel]', wrap).forEach((p) => { p.hidden = p.dataset.panel !== tab.dataset.tab; });
127	    });
128	  });
129	
130	  // ---------- Forms ----------
131	  $$('form[data-form]').forEach((form) => {
132	    form.addEventListener('submit', async (e) => {
133	      e.preventDefault();
134	      const msg = $('.form-msg', form);
135	      let ok = true;
136	      $$('.field', form).forEach((f) => {
137	        const input = $('input, select, textarea', f); if (!input) return;
138	        const bad = input.required && (!input.value.trim() || (input.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(input.value)));
139	        f.classList.toggle('is-invalid', !!bad); if (bad) ok = false;
140	      });
141	      const consent = $('input[name="consent"]', form);
142	      if (consent && consent.required && !consent.checked) { ok = false; toast('Please tick the consent box'); }
143	      if (!ok) return;
144	      const btn = $('button[type="submit"]', form); btn.disabled = true;
